products.push(...[{"id": 101, "name": "Papá, gracias por tu paciencia", "cat": "Cuadros", "theme": "Papá Homero", "image": "assets/nuevo-1.webp", "variants": []}, {"id": 102, "name": "El rey de la casa", "cat": "Cuadros", "theme": "Papá rey", "image": "assets/nuevo-2.webp", "variants": []}, {"id": 103, "name": "Mi héroe, papá", "cat": "Cuadros", "theme": "Papá Iron Man", "image": "assets/nuevo-3.webp", "variants": []}, {"id": 104, "name": "Gracias por tu dedicación", "cat": "Cuadros", "theme": "Papá corbata", "image": "assets/nuevo-4.webp", "variants": []}, {"id": 105, "name": "Te quiero, papá", "cat": "Cuadros", "theme": "Papá espacio", "image": "assets/nuevo-5.webp", "variants": []}, {"id": 106, "name": "Gracias por hacerme de viejo", "cat": "Cuadros", "theme": "Papá Toy Story", "image": "assets/nuevo-6.webp", "variants": []}, {"id": 107, "name": "Paciencia de papá", "cat": "Cuadros", "theme": "Papá Homero", "image": "assets/nuevo-7.webp", "variants": []}, {"id": 108, "name": "Brindemos por ti", "cat": "Cuadros", "theme": "Papá cerveza", "image": "assets/nuevo-8.webp", "variants": []}, {"id": 109, "name": "Yo soy tu padre", "cat": "Cuadros", "theme": "Papá Star Wars", "image": "assets/nuevo-9.webp", "variants": []}, {"id": 110, "name": "Papá blanquiazul", "cat": "Cuadros", "theme": "Papá Alianza", "image": "assets/nuevo-10.webp", "variants": []}, {"id": 111, "name": "Para celebrar a papá", "cat": "Cuadros", "theme": "Papá brindis", "image": "assets/nuevo-11.webp", "variants": []}, {"id": 112, "name": "Tus recuerdos en la cancha", "cat": "Canilleras", "theme": "Canilleras fotos", "image": "assets/nuevo-12.webp", "variants": [["Personalizadas", 65]]}, {"id": 113, "name": "Tu jugador favorito", "cat": "Canilleras", "theme": "Canilleras fútbol", "image": "assets/nuevo-13.webp", "variants": [["Personalizadas", 65]]}, {"id": 114, "name": "Tu compañero fiel", "cat": "Canilleras", "theme": "Canilleras mascota", "image": "assets/nuevo-14.webp", "variants": [["Personalizadas", 65]]}, {"id": 115, "name": "Una historia para llevar", "cat": "Canilleras", "theme": "Canilleras recuerdos", "image": "assets/nuevo-15.webp", "variants": [["Personalizadas", 65]]}, {"id": 116, "name": "Pasión por tus colores", "cat": "Canilleras", "theme": "Canilleras fútbol", "image": "assets/nuevo-16.webp", "variants": [["Personalizadas", 65]]}, {"id": 117, "name": "Hechas para tu partido", "cat": "Canilleras", "theme": "Canilleras fútbol", "image": "assets/nuevo-17.webp", "variants": [["Personalizadas", 65]]}]);products.push(...[{"id": 201, "name": "Huntrix: arte con actitud", "cat": "Cuadros arte", "theme": "Huntrix: arte con actitud", "image": "assets/arte-1.webp", "variants": [["20 × 40 cm", 45], ["40 × 60 cm", 55], ["60 × 80 cm", 75]]}, {"id": 202, "name": "Cristiano: pasión por el fútbol", "cat": "Cuadros arte", "theme": "Cristiano: pasión por el fútbol", "image": "assets/arte-2.webp", "variants": [["20 × 40 cm", 45], ["40 × 60 cm", 55], ["60 × 80 cm", 75]]}, {"id": 203, "name": "Barcos: corazón blanquiazul", "cat": "Cuadros arte", "theme": "Barcos: corazón blanquiazul", "image": "assets/arte-3.webp", "variants": [["20 × 40 cm", 45], ["40 × 60 cm", 55], ["60 × 80 cm", 75]]}, {"id": 204, "name": "Tu historia en un cuadro", "cat": "Cuadros arte", "theme": "Tu historia en un cuadro", "image": "assets/arte-4.webp", "variants": [["20 × 40 cm", 45], ["40 × 60 cm", 55], ["60 × 80 cm", 75]]}, {"id": 205, "name": "Anime a tu estilo", "cat": "Cuadros arte", "theme": "Anime a tu estilo", "image": "assets/arte-5.webp", "variants": [["20 × 40 cm", 45], ["40 × 60 cm", 55], ["60 × 80 cm", 75]]}, {"id": 206, "name": "Arcoíris personalizado", "cat": "Especiales", "theme": "Arcoíris personalizado", "image": "assets/arte-6.webp", "variants": []}]);let bag=[];try{bag=JSON.parse(localStorage.getItem('encantada-bag')||'[]');if(!Array.isArray(bag))bag=[]}catch{}let filter='Todos';const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const q=$('#search').value.toLowerCase();const list=products.filter(p=>(filter==='Todos'||p.cat===filter)&&`${p.name} ${p.theme}`.toLowerCase().includes(q));$('#products').innerHTML=list.length?list.map(p=>`<article class="card"><div class="photo" role="button" tabindex="0" data-id="${p.id}" aria-label="Personalizar ${p.name}"><img loading="lazy" src="${p.image}" alt="${p.name}"><span class="card-brand"><img src="assets/logo-encantada.webp" alt="Encantada Personalizados"></span><span class="label">${p.cat==='Figuras'?'TAMAÑO REAL':'A TU ESTILO'}</span></div><h3>${p.name}</h3><div class="card-bottom"><span>${p.cat==='Figuras'?'Desde S/ 65 · por figura':p.variants?.length?'Desde S/ '+p.variants[0][1]:'Cotiza tu diseño'}</span><button class="add" data-id="${p.id}" aria-label="Personalizar ${p.name}">+</button></div></article>`).join(''):'<p>No encontramos esa temática. Escríbenos para consultar un diseño nuevo.</p>';document.querySelectorAll('[data-id]').forEach(e=>{e.onclick=()=>detail(+e.dataset.id);if(e.classList.contains('photo'))e.onkeydown=k=>{if(k.key==='Enter'||k.key===' '){k.preventDefault();detail(+e.dataset.id)}}})}function detail(id){const p=products.find(p=>p.id===id);$('#detail').innerHTML=`<div class="dialog-brand"><img src="assets/logo-encantada.webp" alt="Encantada Personalizados"><span>Un detalle tuyo. El encanto de siempre.</span></div><div class="detail-grid"><img src="${p.image}" alt="${p.name}"><div><span class="eyebrow">HECHO A TU MEDIDA</span><h2>${p.name}</h2><form id="personalize"><label>Medida<select name="size">${p.cat==='Figuras'?['1.50 m|65','1.60 m|75','1.70 m|85','1.80 m|95'].map(v=>{let[s,n]=v.split('|');return `<option value="${s}" data-price="${n}">${s} — S/ ${n}</option>`}).join(''):p.variants?.length?p.variants.map(([size,price])=>`<option value="${size}" data-price="${price}">${size} — S/ ${price}</option>`).join(''):'<option>Por coordinar / cotización</option>'}</select></label><label>Cantidad<input name="qty" type="number" min="1" max="100" value="1" required></label><label>Nombre, personaje y detalles<textarea name="notes" maxlength="600" placeholder="Ej.: Valentina, 5 años, tonos rosados" required></textarea></label><p class="price-note">${p.cat==='Figuras'?'Precio por figura delgada. Una figura más ancha puede cambiar el precio.':'El equipo confirmará las medidas y el precio.'} Foto de trabajo realizado como referencia. El costo de entrega se confirma aparte.</p><button class="primary">Agregar a mi pedido +</button></form></div></div>`;$('#personalize').onsubmit=e=>{e.preventDefault();const f=e.target;bag.push({id:p.id,qty:+f.qty.value,size:f.size.value,price:+(f.size.selectedOptions[0].dataset.price||0),notes:f.notes.value});save();$('#productDialog').close();$('#toast').textContent='¡Agregado a tu pedido! ♡';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)};$('#productDialog').showModal()}function save(){localStorage.setItem('encantada-bag',JSON.stringify(bag));$('#count').textContent=bag.reduce((n,p)=>n+p.qty,0)}function showBag(){const total=bag.reduce((n,p)=>n+p.price*p.qty,0);$('#bagItems').innerHTML=bag.length?bag.map((i,n)=>{const p=products.find(p=>p.id===i.id);return `<div class="bag-row"><img src="${p.image}" alt=""><div><b>${p.name}</b><p>${i.qty} × ${esc(i.size)} · ${i.price?'S/ '+i.price:'Por cotizar'}</p><p>${esc(i.notes)}</p></div><button class="remove" data-remove="${n}" aria-label="Quitar ${p.name}">Quitar</button></div>`}).join('')+`<p>Subtotal referencial: <b>S/ ${total.toFixed(2)}</b>${bag.some(i=>!i.price)?' + productos por cotizar':''}</p>`:'<p>Tu pedido está esperando su primer detalle. Explora el catálogo y elige tu favorito.</p>';$('#checkout').hidden=!bag.length;document.querySelectorAll('[data-remove]').forEach(e=>e.onclick=()=>{bag.splice(+e.dataset.remove,1);save();showBag()});if(!$('#bagDialog').open)$('#bagDialog').showModal()}document.querySelectorAll('[data-filter]').forEach(e=>e.onclick=()=>{filter=e.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===e));render()});$('#search').oninput=render;$('#openBag').onclick=showBag;document.querySelectorAll('.close').forEach(e=>e.onclick=()=>e.closest('dialog').close());$('#checkout').onsubmit=e=>{e.preventDefault();const f=e.target;let msg=`¡Hola Encantada! Soy ${f.customer.value}. Quisiera cotizar este pedido:\n\n`+bag.map(i=>`${i.qty} × ${products.find(p=>p.id===i.id).name}\nMedida: ${i.size}\nDetalle: ${i.notes}\nPrecio referencial: ${i.price?'S/ '+i.price+' por figura':'por cotizar'}`).join('\n\n')+`\n\nFecha del evento: ${f.date.value}\nDistrito / ciudad: ${f.city.value}\nEntrega: ${f.delivery.value}\nPago: ${f.payment.value}\nPor favor, confirmar disponibilidad, total, pago y entrega.`;window.open('https://wa.me/51934520463?text='+encodeURIComponent(msg),'_blank','noopener')};$('#checkout [name=date]').min=new Date().toLocaleDateString('en-CA');save();render();

const reduced=matchMedia('(prefers-reduced-motion: reduce)');const observe=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observe.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.custom,.steps,.faq').forEach(e=>{e.classList.add('reveal');observe.observe(e)});if(matchMedia('(hover:hover)').matches&&!reduced.matches){document.addEventListener('pointermove',e=>{const card=e.target.closest('.photo,.hero-art');if(!card)return;const r=card.getBoundingClientRect();card.style.transform=`perspective(1000px) rotateX(${-(e.clientY-r.top-r.height/2)/35}deg) rotateY(${(e.clientX-r.left-r.width/2)/35}deg)`});document.addEventListener('pointerout',e=>{const c=e.target.closest('.photo,.hero-art');if(c&&!c.contains(e.relatedTarget))c.style.transform=''})}

// La carga acompaña la preparación real de la página, sin esperas artificiales.
const splash=document.getElementById('brandLoader');function finishLoading(){if(splash){splash.classList.add('loaded');splash.setAttribute('aria-hidden','true');setTimeout(()=>splash.remove(),450)}}if(document.readyState==='complete')finishLoading();else window.addEventListener('load',finishLoading,{once:true});setTimeout(finishLoading,4000);

document.getElementById('showYape').onclick=()=>document.getElementById('yapeDialog').showModal();
